-- 028 — apoiadores da comunidade. O patrocínio por edição (017) continua;
-- aqui entra quem apoia a comunidade como um todo: empresa, faculdade ou
-- loja que dá dinheiro, espaço, comida, prêmio, mentoria ou divulgação.
-- O dono/organizador cadastra e ordena; a página pública mostra "Quem apoia".

CREATE TABLE community_supporters (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "communityId" INTEGER NOT NULL REFERENCES communities("id") ON DELETE CASCADE,
  "name" TEXT NOT NULL,
  -- logo e link: https validado na API (mesmo padrão do logo da comunidade)
  "logoUrl" TEXT,
  "url" TEXT,
  "kind" TEXT NOT NULL DEFAULT 'outro'
    CHECK ("kind" IN ('dinheiro', 'espaco', 'comida', 'premio', 'mentoria', 'divulgacao', 'outro')),
  "description" TEXT,
  -- ordem na página (menor primeiro)
  "position" INTEGER NOT NULL DEFAULT 0,
  "createdBy" INTEGER REFERENCES members("id"),
  "createdAt" TEXT NOT NULL DEFAULT sqlite_now()
);
CREATE INDEX idx_community_supporters_community ON community_supporters ("communityId", "position");
-- o mesmo nome não entra duas vezes na mesma comunidade (nem em cadastro
-- simultâneo); a lib devolve 409
CREATE UNIQUE INDEX idx_community_supporters_name ON community_supporters ("communityId", lower("name"));

-- "quero apoiar esta comunidade": o lead da porta comercial (001/018) ganha
-- a comunidade e o tipo de apoio oferecido. Lead sem comunidade segue sendo
-- da plataforma (/empresas, /organizar).
ALTER TABLE leads DROP CONSTRAINT leads_interest_check;
ALTER TABLE leads ADD CONSTRAINT leads_interest_check
  CHECK ("interest" IN ('desafio', 'edicao', 'talento', 'outro', 'organizar', 'comunidade'));
ALTER TABLE leads ADD COLUMN "communityId" INTEGER REFERENCES communities("id") ON DELETE CASCADE;
ALTER TABLE leads ADD COLUMN "supportKind" TEXT
  CHECK ("supportKind" IS NULL OR "supportKind" IN ('dinheiro', 'espaco', 'comida', 'premio', 'mentoria', 'divulgacao', 'outro'));
ALTER TABLE leads ADD CONSTRAINT leads_comunidade_check
  CHECK (("interest" = 'comunidade') = ("communityId" IS NOT NULL));
CREATE INDEX idx_leads_community ON leads ("communityId", "createdAt" DESC) WHERE "communityId" IS NOT NULL;
